CONTENTS = {'app/routes/admin.py': 'from __future__ import annotations\nfrom app.services.search_providers import serper_status\n\nfrom pathlib import Path\nfrom urllib.parse import urlencode\n\nfrom fastapi import APIRouter, Request\nfrom fastapi.responses import FileResponse, HTMLResponse, JSONResponse, RedirectResponse, Response\nfrom sqlalchemy import func, or_, select\nfrom sqlalchemy.exc import IntegrityError\nfrom sqlalchemy.orm import selectinload\n\nfrom ..config import settings\nfrom ..database import SessionLocal\nfrom ..models import AdminUser, Disaster, DiscoveryCandidate, MissingPerson, Source, Submission\nfrom ..security import verify_password\nfrom ..services.discovery import discover_candidates, generate_queries, google_search_url\nfrom ..services.wide_discovery import collect_known_source_scopes, generate_wide_queries, run_wide_discovery\nfrom ..services.search_providers import SearchProviderUnavailable, brave_status\nfrom ..services.candidate_extract import candidate_mentions_multiple_people, extract_candidate_people_names, extract_candidate_prefill\nfrom ..services.candidate_chatgpt_prefill import build_candidate_chatgpt_prefill_prompt\nfrom ..services.ai_review import build_free_ai_review_prompt, parse_free_ai_review\nfrom ..services.master_records import apply_submission_to_master\nfrom ..services.duplicates import find_duplicates\nfrom ..services.exports import build_csv, build_xlsx\nfrom ..services.files import save_image\nfrom ..services.source_images import discover_public_post_image, discover_public_post_text, download_public_source_image, is_allowed_public_image_url\nfrom ..services.source_ocr import extract_ocr_text, ocr_available\nfrom ..services.normalization import affected_location_match, canonicalize_url, detect_platform\nfrom ..services.priority_sources import priority_manual_searches\nfrom ..services.share_cards import build_share_card\nfrom .common import admin_gate, audit, next_case_number, parse_date, parse_int, parse_time, render\n\nrouter = APIRouter()\n\n\ndef _normalize_gender(value) -> str | None:\n    folded = str(value or "").strip().casefold()\n    if folded in {"male", "m", "पुरुष"}:\n        return "Male"\n    if folded in {"female", "f", "महिला"}:\n        return "Female"\n    return None\n\n\ndef _exact_name_matches(db, disaster_id: int, name: str) -> list[MissingPerson]:\n    folded = name.strip().casefold()\n    if not folded:\n        return []\n    people = db.scalars(\n        select(MissingPerson).where(\n            MissingPerson.disaster_id == disaster_id,\n            MissingPerson.archived.is_(False),\n        )\n    ).all()\n    return [\n        person\n        for person in people\n        if person.name.strip().casefold() == folded\n        or (person.name_ne and person.name_ne.strip().casefold() == folded)\n    ]\n\n\ndef _pending_name_matches(db, disaster_id: int, name: str) -> list[Submission]:\n    folded = name.strip().casefold()\n    if not folded:\n        return []\n    submissions = db.scalars(\n        select(Submission).where(\n            Submission.disaster_id == disaster_id,\n            Submission.status == "pending",\n        )\n    ).all()\n    return [\n        item for item in submissions\n        if (item.name or "").strip().casefold() == folded\n    ]\n\n\n@router.get("/admin/media/{filename}")\ndef admin_media(request: Request, filename: str):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if Path(filename).name != filename:\n        return HTMLResponse("Not found", status_code=404)\n    with SessionLocal() as db:\n        referenced = db.scalar(\n            select(func.count()).select_from(Submission).where(Submission.photo_path == filename)\n        ) or db.scalar(\n            select(func.count()).select_from(MissingPerson).where(MissingPerson.photo_path == filename)\n        )\n        if not referenced:\n            return HTMLResponse("Not found", status_code=404)\n    path = settings.upload_dir / filename\n    if not path.is_file():\n        return HTMLResponse("Not found", status_code=404)\n    return FileResponse(path)\n\n\n@router.get("/admin/login", response_class=HTMLResponse)\ndef login_page(request: Request):\n    return render(request, "admin_login.html", error=None)\n\n\n@router.post("/admin/login", response_class=HTMLResponse)\nasync def login(request: Request):\n    form = await request.form()\n    username = str(form.get("username") or "")\n    password = str(form.get("password") or "")\n    with SessionLocal() as db:\n        admin = db.scalar(select(AdminUser).where(AdminUser.username == username, AdminUser.active.is_(True)))\n        if admin is None or not verify_password(password, admin.password_hash):\n            return render(request, "admin_login.html", error="Invalid credentials")\n        request.session["admin"] = admin.username\n        audit(db, request, "login", "admin", admin.id)\n        db.commit()\n    return RedirectResponse("/admin", status_code=303)\n\n\n@router.post("/admin/logout")\ndef logout(request: Request):\n    request.session.clear()\n    return RedirectResponse("/admin/login", status_code=303)\n\n\n@router.get("/admin", response_class=HTMLResponse)\ndef admin_dashboard(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        stats = {\n            "people": db.scalar(select(func.count(MissingPerson.id)).where(MissingPerson.archived.is_(False))) or 0,\n            "published": db.scalar(\n                select(func.count(MissingPerson.id)).where(\n                    MissingPerson.published.is_(True), MissingPerson.archived.is_(False)\n                )\n            )\n            or 0,\n            "pending": db.scalar(select(func.count(Submission.id)).where(Submission.status == "pending")) or 0,\n            "candidates": db.scalar(\n                select(func.count(DiscoveryCandidate.id)).where(DiscoveryCandidate.status == "new")\n            )\n            or 0,\n            "sources": db.scalar(select(func.count(Source.id))) or 0,\n        }\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_dashboard.html", stats=stats, disasters=disasters)\n\n\n@router.get("/admin/events", response_class=HTMLResponse)\ndef admin_events(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_events.html", disasters=disasters, error=None)\n\n\n@router.post("/admin/events")\nasync def admin_event_create(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    code = str(form.get("code") or "").strip().upper()\n    name = str(form.get("name") or "").strip()\n    start_date = parse_date(form.get("start_date"))\n    if not code or not name or not start_date:\n        return RedirectResponse("/admin/events", status_code=303)\n    with SessionLocal() as db:\n        disaster = Disaster(\n            code=code,\n            name=name,\n            disaster_type=str(form.get("disaster_type") or "flood").strip(),\n            start_date=start_date,\n            affected_locations=str(form.get("affected_locations") or "").strip(),\n            active=True,\n        )\n        db.add(disaster)\n        try:\n            db.flush()\n            audit(db, request, "create_event", "disaster", disaster.id, name)\n            db.commit()\n        except IntegrityError:\n            db.rollback()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.post("/admin/events/{disaster_id}/update")\nasync def admin_event_update(request: Request, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Not found", status_code=404)\n        disaster.name = str(form.get("name") or disaster.name).strip()\n        disaster.disaster_type = str(form.get("disaster_type") or disaster.disaster_type).strip()\n        disaster.affected_locations = str(form.get("affected_locations") or "").strip()\n        disaster.active = str(form.get("active") or "") == "on"\n        audit(db, request, "update_event", "disaster", disaster.id, disaster.name)\n        db.commit()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.get("/admin/people", response_class=HTMLResponse)\ndef admin_people(request: Request, disaster_id: int | None = None, q: str = ""):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        stmt = (\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .order_by(MissingPerson.created_at.desc())\n        )\n        if disaster_id:\n            stmt = stmt.where(MissingPerson.disaster_id == disaster_id)\n        if q.strip():\n            pattern = f"%{q.strip()}%"\n            stmt = stmt.where(\n                or_(\n                    MissingPerson.name.ilike(pattern),\n                    MissingPerson.name_ne.ilike(pattern),\n                    MissingPerson.case_number.ilike(pattern),\n                )\n            )\n        people = list(db.scalars(stmt.limit(500)).all())\n        return render(\n            request,\n            "admin_people.html",\n            people=people,\n            disasters=disasters,\n            selected_disaster=disaster_id,\n            q=q,\n        )\n\n\n@router.get("/admin/people/{person_id}", response_class=HTMLResponse)\ndef admin_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.scalar(\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .where(MissingPerson.id == person_id)\n        )\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        merge_targets = list(\n            db.scalars(\n                select(MissingPerson).where(\n                    MissingPerson.disaster_id == person.disaster_id,\n                    MissingPerson.id != person.id,\n                    MissingPerson.archived.is_(False),\n                ).order_by(MissingPerson.name)\n            ).all()\n        )\n        return render(\n            request,\n            "admin_person.html",\n            person=person,\n            error=None,\n            public_url=f"{settings.public_base_url}/person/{person.case_number}",\n            merge_targets=merge_targets,\n        )\n\n\n@router.post("/admin/people/{person_id}/edit")\nasync def admin_person_edit(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        person.name = str(form.get("name") or person.name).strip()\n        person.name_ne = str(form.get("name_ne") or "").strip() or None\n        person.age = parse_int(form.get("age"))\n        person.gender = _normalize_gender(form.get("gender"))\n        person.last_seen_date = parse_date(form.get("last_seen_date"))\n        person.last_seen_time = parse_time(form.get("last_seen_time"))\n        person.last_seen_location = str(form.get("last_seen_location") or "").strip()\n        person.clothing = str(form.get("clothing") or "").strip() or None\n        person.identification_details = str(form.get("identification_details") or "").strip() or None\n        person.public_contact_number = str(form.get("public_contact_number") or "").strip() or None\n        person.residential_address_private = str(form.get("residential_address_private") or "").strip() or None\n        audit(db, request, "edit_person", "person", person.id)\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/publish")\ndef admin_publish(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.published = not person.published\n            audit(db, request, "publish_toggle", "person", person.id, str(person.published))\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/archive")\ndef admin_archive(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.archived = True\n            person.published = False\n            audit(db, request, "archive_person", "person", person.id)\n            db.commit()\n    return RedirectResponse("/admin/people", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/merge")\nasync def admin_merge_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    target_id = parse_int(form.get("target_person_id"))\n    if not target_id or target_id == person_id:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        source = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == person_id)\n        )\n        target = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == target_id)\n        )\n        if source is None or target is None or source.disaster_id != target.disaster_id:\n            return HTMLResponse("Invalid merge target", status_code=400)\n\n        target_urls = {item.url for item in target.sources}\n        for source_item in list(source.sources):\n            if source_item.url in target_urls:\n                db.delete(source_item)\n            else:\n                source_item.person_id = target.id\n                target_urls.add(source_item.url)\n\n        db.execute(\n            Submission.__table__.update()\n            .where(Submission.person_id == source.id)\n            .values(person_id=target.id)\n        )\n\n        # Fill only blank canonical fields. The target remains the admin-selected master record.\n        for field in [\n            "name_ne", "age", "gender", "photo_path", "residential_address_private",\n            "last_seen_date", "last_seen_time", "clothing", "identification_details",\n            "public_contact_number", "private_contact_number",\n        ]:\n            if getattr(target, field) in (None, "") and getattr(source, field) not in (None, ""):\n                setattr(target, field, getattr(source, field))\n        if not target.last_seen_location and source.last_seen_location:\n            target.last_seen_location = source.last_seen_location\n\n        source.archived = True\n        source.published = False\n        audit(\n            db,\n            request,\n            "merge_duplicate_person",\n            "person",\n            source.id,\n            f"merged_into={target.id}; target_case={target.case_number}",\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{target_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/source")\nasync def admin_add_source(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    url = canonicalize_url(str(form.get("url") or ""))\n    if not url:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        if db.get(MissingPerson, person_id) is None:\n            return HTMLResponse("Not found", status_code=404)\n        existing = db.scalar(select(Source).where(Source.person_id == person_id, Source.url == url))\n        if existing is None:\n            source = Source(\n                person_id=person_id,\n                platform=str(form.get("platform") or "facebook").strip(),\n                url=url,\n                source_name=str(form.get("source_name") or "").strip() or None,\n                source_text=str(form.get("source_text") or "").strip() or None,\n            )\n            db.add(source)\n            db.flush()\n            audit(db, request, "add_source", "source", source.id, url)\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.get("/admin/submissions", response_class=HTMLResponse)\ndef admin_submissions(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        submissions = list(\n            db.scalars(\n                select(Submission).where(Submission.status == "pending").order_by(Submission.created_at.desc())\n            ).all()\n        )\n        duplicate_map: dict[int, list[tuple[MissingPerson, float]]] = {}\n        location_match_map: dict[int, bool] = {}\n        disasters_by_id = {d.id: d for d in db.scalars(select(Disaster)).all()}\n        for sub in submissions:\n            disaster = disasters_by_id.get(sub.disaster_id)\n            location_match_map[sub.id] = bool(\n                disaster and affected_location_match(sub.last_seen_location, disaster.affected_locations)\n            )\n            if sub.kind == "missing_report" and sub.name:\n                duplicate_map[sub.id] = find_duplicates(\n                    db,\n                    disaster_id=sub.disaster_id,\n                    name=sub.name,\n                    location=sub.last_seen_location,\n                    age=sub.age,\n                    phone=sub.public_contact_number,\n                )\n        people = list(\n            db.scalars(\n                select(MissingPerson).where(MissingPerson.archived.is_(False)).order_by(MissingPerson.name)\n            ).all()\n        )\n        people_by_disaster: dict[int, list[MissingPerson]] = {}\n        for person in people:\n            people_by_disaster.setdefault(person.disaster_id, []).append(person)\n        return render(\n            request,\n            "admin_submissions.html",\n            submissions=submissions,\n            duplicate_map=duplicate_map,\n            location_match_map=location_match_map,\n            people_by_disaster=people_by_disaster,\n        )\n\n\n@router.post("/admin/submissions/{submission_id}/approve-new")\ndef approve_submission_new(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub is None or sub.status != "pending" or not sub.name:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        disaster = db.get(Disaster, sub.disaster_id)\n        if disaster is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        person = MissingPerson(\n            case_number=next_case_number(db, disaster),\n            disaster_id=sub.disaster_id,\n            name=sub.name,\n            name_ne=sub.name_ne,\n            age=sub.age,\n            gender=sub.gender,\n            photo_path=sub.photo_path,\n            residential_address_private=sub.residential_address_private,\n            last_seen_date=sub.last_seen_date,\n            last_seen_time=sub.last_seen_time,\n            last_seen_location=sub.last_seen_location or "Unknown",\n            clothing=sub.clothing,\n            identification_details=sub.identification_details,\n            public_contact_number=sub.public_contact_number,\n            private_contact_number=sub.reporter_phone_private,\n            published=False,\n        )\n        db.add(person)\n        db.flush()\n        sub.person_id = person.id\n        sub.status = "approved"\n        if sub.social_url:\n            db.add(\n                Source(\n                    person_id=person.id,\n                    platform=detect_platform(sub.social_url),\n                    url=sub.social_url,\n                    source_text=sub.notes,\n                )\n            )\n        audit(db, request, "approve_submission_new", "person", person.id, f"submission={sub.id}")\n        db.commit()\n        return RedirectResponse(f"/admin/people/{person.id}", status_code=303)\n\n\n@router.post("/admin/submissions/{submission_id}/attach")\nasync def attach_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    person_id = parse_int(form.get("person_id"))\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        person = db.get(MissingPerson, person_id) if person_id else None\n        if sub is None or person is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        if person.disaster_id != sub.disaster_id:\n            return HTMLResponse("Cannot attach a submission to a person from a different disaster", status_code=400)\n        if sub.status != "pending":\n            return RedirectResponse("/admin/submissions", status_code=303)\n\n        updated_fields = apply_submission_to_master(\n            person,\n            sub,\n        )\n\n        if sub.social_url:\n            existing = db.scalar(select(Source).where(Source.person_id == person.id, Source.url == sub.social_url))\n            if existing is None:\n                db.add(\n                    Source(\n                        person_id=person.id,\n                        platform=detect_platform(sub.social_url),\n                        url=sub.social_url,\n                        source_text=sub.notes,\n                    )\n                )\n        sub.person_id = person.id\n        sub.status = "attached"\n        audit(\n            db,\n            request,\n            "attach_submission",\n            "person",\n            person.id,\n            (\n                f"submission={sub.id}; "\n                f"master_fields_updated={\',\'.join(updated_fields) or \'none\'}"\n            ),\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n\n@router.post(\n    "/admin/submissions/{submission_id}/edit"\n)\nasync def edit_pending_submission(\n    request: Request,\n    submission_id: int,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    with SessionLocal() as db:\n        sub = db.get(\n            Submission,\n            submission_id,\n        )\n\n        if (\n            sub is None\n            or sub.status != "pending"\n        ):\n            return RedirectResponse(\n                "/admin/submissions",\n                status_code=303,\n            )\n\n        name = str(\n            form.get("name")\n            or ""\n        ).strip()\n\n        if (\n            sub.kind == "missing_report"\n            and not name\n        ):\n            return HTMLResponse(\n                "Name is required",\n                status_code=400,\n            )\n\n        sub.name = name or sub.name\n\n        sub.name_ne = (\n            str(\n                form.get("name_ne")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.age = parse_int(\n            form.get("age")\n        )\n\n        sub.gender = _normalize_gender(form.get("gender"))\n\n        sub.last_seen_date = parse_date(\n            form.get("last_seen_date")\n        )\n\n        sub.last_seen_time = parse_time(\n            form.get("last_seen_time")\n        )\n\n        sub.last_seen_location = (\n            str(\n                form.get(\n                    "last_seen_location"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.clothing = (\n            str(\n                form.get("clothing")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.identification_details = (\n            str(\n                form.get(\n                    "identification_details"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.public_contact_number = (\n            str(\n                form.get(\n                    "public_contact_number"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        photo_upload = form.get(\n            "photo"\n        )\n\n        if (\n            photo_upload is not None\n            and getattr(\n                photo_upload,\n                "filename",\n                "",\n            )\n        ):\n            try:\n                photo_path = await save_image(\n                    photo_upload,\n                    settings.upload_dir,\n                )\n            except ValueError as exc:\n                return HTMLResponse(\n                    str(exc),\n                    status_code=400,\n                )\n\n            if photo_path:\n                sub.photo_path = photo_path\n\n        audit(\n            db,\n            request,\n            "edit_pending_submission",\n            "submission",\n            sub.id,\n            "admin-reviewed extracted details",\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.post("/admin/submissions/{submission_id}/reject")\ndef reject_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub:\n            sub.status = "rejected"\n            audit(db, request, "reject_submission", "submission", sub.id)\n            db.commit()\n    return RedirectResponse("/admin/submissions", status_code=303)\n\n\n@router.get("/admin/discovery", response_class=HTMLResponse)\ndef discovery_page(\n    request: Request,\n    disaster_id: int | None = None,\n    platform: str = "facebook",\n    view: str = "review",\n    q: str = "",\n    wide_queries: int | None = None,\n    wide_raw: int | None = None,\n    wide_added: int | None = None,\n    wide_error: int | None = None,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    allowed_views = {"review", "relevant", "irrelevant", "processed"}\n    view = view.casefold().strip()\n    if view not in allowed_views:\n        view = "review"\n\n    with SessionLocal() as db:\n        disasters = list(\n            db.scalars(\n                select(Disaster).order_by(\n                    Disaster.active.desc(),\n                    Disaster.start_date.desc(),\n                )\n            ).all()\n        )\n        selected = (\n            db.get(Disaster, disaster_id)\n            if disaster_id\n            else next((d for d in disasters if d.active), disasters[0] if disasters else None)\n        )\n\n        queries = (\n            generate_queries(selected, platform=platform)\n            if selected\n            else []\n        )\n\n        wide_provider_status = serper_status()\n        wide_query_plan: list[str] = []\n        published_urls: set[str] = set()\n        queue_counts = {\n            "review": 0,\n            "relevant": 0,\n            "irrelevant": 0,\n            "processed": 0,\n        }\n        candidates: list[DiscoveryCandidate] = []\n\n        if selected:\n            if platform == "facebook":\n                scopes = collect_known_source_scopes(db, selected.id)\n                wide_query_plan = generate_wide_queries(\n                    selected,\n                    source_scopes=scopes,\n                )\n\n            published_urls = set(\n                db.scalars(\n                    select(Source.url)\n                    .join(MissingPerson, Source.person_id == MissingPerson.id)\n                    .where(\n                        MissingPerson.disaster_id == selected.id,\n                        MissingPerson.published.is_(True),\n                        MissingPerson.archived.is_(False),\n                    )\n                ).all()\n            )\n\n            base_conditions = [\n                DiscoveryCandidate.disaster_id == selected.id,\n                DiscoveryCandidate.platform == platform,\n            ]\n\n            status_groups = {\n                "review": ["new", "needs_ai"],\n                "relevant": ["relevant"],\n                "irrelevant": ["irrelevant", "rejected"],\n                "processed": ["reviewed"],\n            }\n\n            for key, statuses in status_groups.items():\n                count_stmt = (\n                    select(func.count(DiscoveryCandidate.id))\n                    .where(*base_conditions)\n                    .where(DiscoveryCandidate.status.in_(statuses))\n                )\n                if key in {"review", "relevant"} and published_urls:\n                    count_stmt = count_stmt.where(\n                        DiscoveryCandidate.url.notin_(published_urls)\n                    )\n                queue_counts[key] = db.scalar(count_stmt) or 0\n\n            stmt = (\n                select(DiscoveryCandidate)\n                .where(*base_conditions)\n                .where(DiscoveryCandidate.status.in_(status_groups[view]))\n                .order_by(DiscoveryCandidate.found_at.desc())\n            )\n\n            if view in {"review", "relevant"} and published_urls:\n                stmt = stmt.where(\n                    DiscoveryCandidate.url.notin_(published_urls)\n                )\n\n            if q.strip():\n                pattern = f"%{q.strip()}%"\n                stmt = stmt.where(\n                    or_(\n                        DiscoveryCandidate.title.ilike(pattern),\n                        DiscoveryCandidate.snippet.ilike(pattern),\n                    )\n                )\n\n            candidates = list(db.scalars(stmt.limit(300)).all())\n\n        base_params = {\n            "disaster_id": selected.id if selected else "",\n            "platform": platform,\n        }\n        queue_links = {\n            key: "/admin/discovery?" + urlencode(\n                {**base_params, "view": key, **({"q": q.strip()} if q.strip() else {})}\n            )\n            for key in allowed_views\n        }\n        clear_search_url = "/admin/discovery?" + urlencode(\n            {**base_params, "view": view}\n        )\n\n        priority_searches = []\n        if selected and platform == "facebook":\n            priority_searches = [\n                {\n                    **item,\n                    "url": google_search_url(\n                        item["query"],\n                        selected.start_date,\n                    ),\n                }\n                for item in priority_manual_searches(selected)\n            ]\n\n        return render(\n            request,\n            "admin_discovery.html",\n            disasters=disasters,\n            selected=selected,\n            platform=platform,\n            view=view,\n            q=q,\n            queue_counts=queue_counts,\n            queue_links=queue_links,\n            clear_search_url=clear_search_url,\n            queries=[(item, google_search_url(item, selected.start_date)) for item in queries] if selected else [],\n            priority_searches=priority_searches,\n            candidates=candidates,\n            bot_message=None,\n            wide_stats=(\n                {"queries": wide_queries, "raw": wide_raw, "added": wide_added}\n                if wide_queries is not None\n                else None\n            ),\n            wide_provider_status=wide_provider_status,\n            wide_query_plan=wide_query_plan,\n            wide_error=bool(wide_error),\n        )\n\n\n@router.post("/admin/discovery/run")\nasync def discovery_run(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook")\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id) if disaster_id else None\n        if disaster is None:\n            return RedirectResponse("/admin/discovery", status_code=303)\n        added = discover_candidates(db, disaster, platform=platform)\n        audit(db, request, "run_discovery_bot", "disaster", disaster.id, f"platform={platform}; added={added}")\n        db.commit()\n    return RedirectResponse(f"/admin/discovery?disaster_id={disaster_id}&platform={platform}", status_code=303)\n\n\n\n@router.post("/admin/wide-discovery/run")\nasync def wide_discovery_run(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    with SessionLocal() as db:\n        disaster = (\n            db.get(\n                Disaster,\n                disaster_id,\n            )\n            if disaster_id\n            else None\n        )\n\n        if disaster is None:\n            return RedirectResponse(\n                "/admin/discovery",\n                status_code=303,\n            )\n\n        try:\n            stats = run_wide_discovery(\n                db,\n                disaster,\n            )\n        except SearchProviderUnavailable:\n            return RedirectResponse(\n                (\n                    "/admin/discovery"\n                    f"?disaster_id={disaster_id}"\n                    "&platform=facebook"\n                    "&wide_error=1"\n                ),\n                status_code=303,\n            )\n\n        audit(\n            db,\n            request,\n            "run_wide_discovery",\n            "disaster",\n            disaster.id,\n            (\n                f"queries={stats[\'queries\']}; "\n                f"raw={stats[\'raw_results\']}; "\n                f"needs_ai={stats[\'needs_ai\']}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        (\n            "/admin/discovery"\n            f"?disaster_id={disaster_id}"\n            "&platform=facebook"\n            f"&wide_queries={stats[\'queries\']}"\n            f"&wide_raw={stats[\'raw_results\']}"\n            f"&wide_added={stats[\'needs_ai\']}"\n        ),\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/manual")\nasync def discovery_manual(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    url = canonicalize_url(str(form.get("url") or ""))\n    platform = str(form.get("platform") or "facebook").strip()\n    title = str(form.get("title") or "").strip()\n    manual_text = str(form.get("snippet") or "").strip()\n    search_query = str(form.get("search_query") or "").strip()\n\n    if not disaster_id or not url:\n        return RedirectResponse("/admin/discovery", status_code=303)\n\n    with SessionLocal() as db:\n        existing = db.scalar(\n            select(DiscoveryCandidate).where(\n                DiscoveryCandidate.disaster_id == disaster_id,\n                DiscoveryCandidate.url == url,\n            )\n        )\n\n        if existing is None:\n            query_value = (\n                f"manual:{search_query}"\n                if search_query\n                else "manual-url"\n            )\n            candidate = DiscoveryCandidate(\n                disaster_id=disaster_id,\n                platform=platform,\n                query=query_value,\n                url=url,\n                title=title or None,\n                snippet=manual_text or None,\n            )\n            db.add(candidate)\n            db.flush()\n            audit(\n                db,\n                request,\n                "add_manual_candidate",\n                "discovery_candidate",\n                candidate.id,\n                (\n                    f"url={url}; "\n                    f"search_context={search_query or \'direct\'}"\n                ),\n            )\n        else:\n            candidate = existing\n            changes: list[str] = []\n\n            # Human-entered context can enrich an existing automated result\n            # without destroying the original indexed evidence.\n            if title and not (candidate.title or "").strip():\n                candidate.title = title\n                changes.append("title")\n\n            if manual_text:\n                current = (candidate.snippet or "").strip()\n                if manual_text not in current:\n                    candidate.snippet = (\n                        f"{current}\\\\n\\\\n[Manual context]\\\\n{manual_text}"\n                        if current\n                        else manual_text\n                    )\n                    changes.append("context")\n\n            audit(\n                db,\n                request,\n                "update_manual_candidate_context",\n                "discovery_candidate",\n                candidate.id,\n                (\n                    f"url={url}; "\n                    f"search_context={search_query or \'direct\'}; "\n                    f"changes={\',\'.join(changes) or \'none\'}"\n                ),\n            )\n\n        db.commit()\n        candidate_id = candidate.id\n\n    return RedirectResponse(\n        f"/admin/discovery/{candidate_id}",\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/{candidate_id}/status")\nasync def discovery_candidate_status(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    action = str(form.get("status_action") or "").strip().casefold()\n    current_view = str(form.get("view") or "review").strip().casefold()\n    platform = str(form.get("platform") or "facebook").strip()\n    q = str(form.get("q") or "").strip()\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        if action == "relevant":\n            candidate.status = "relevant"\n        elif action == "irrelevant":\n            candidate.status = "irrelevant"\n        elif action == "restore":\n            candidate.status = "needs_ai"\n        elif action == "processed":\n            candidate.status = "reviewed"\n        elif action == "reopen":\n            candidate.status = "relevant"\n        else:\n            return HTMLResponse("Invalid discovery status", status_code=400)\n\n        audit(\n            db,\n            request,\n            "classify_discovery_candidate",\n            "discovery_candidate",\n            candidate.id,\n            f"status={candidate.status}",\n        )\n        db.commit()\n\n        params = {\n            "disaster_id": candidate.disaster_id,\n            "platform": platform,\n            "view": current_view if current_view in {"review", "relevant", "irrelevant", "processed"} else "review",\n        }\n        if q:\n            params["q"] = q\n\n    if action == "relevant":\n        # Relevant is the hand-off point from discovery triage into\n        # detailed source review and ChatGPT-assisted prefill.\n        return RedirectResponse(\n            f"/admin/discovery/{candidate_id}#chatgpt-prefill",\n            status_code=303,\n        )\n\n    return RedirectResponse(\n        "/admin/discovery?" + urlencode(params),\n        status_code=303,\n    )\n\n\n@router.get("/admin/discovery/{candidate_id}/public-details")\nasync def discovery_candidate_public_details(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return JSONResponse({"error": "unknown disaster"}, status_code=404)\n\n        source_text = ""\n        if candidate.platform == "facebook":\n            source_text = (await discover_public_post_text(candidate.url)) or ""\n\n        evidence_text = source_text or candidate.snippet or ""\n        prefill = extract_candidate_prefill(\n            candidate,\n            disaster,\n            source_text=source_text,\n        )\n        people = extract_candidate_people_names(\n            candidate,\n            source_text=source_text,\n        )\n        multiple_people = candidate_mentions_multiple_people(\n            candidate,\n            source_text=source_text,\n        )\n\n        return JSONResponse(\n            {\n                "text": evidence_text,\n                "full_public_text_available": bool(source_text),\n                "people": people,\n                "multiple_people": multiple_people,\n                "age": prefill.get("age"),\n                "last_seen_location": prefill.get("last_seen_location"),\n                "public_contact_number": prefill.get("public_contact_number"),\n            }\n        )\n\n\n@router.get("/admin/discovery/{candidate_id}/duplicate-check")\ndef discovery_candidate_duplicate_check(\n    request: Request,\n    candidate_id: int,\n    name: str = "",\n    location: str = "",\n    age: int | None = None,\n    phone: str = "",\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n\n        exact = _exact_name_matches(db, candidate.disaster_id, name)\n        fuzzy = find_duplicates(\n            db,\n            disaster_id=candidate.disaster_id,\n            name=name,\n            location=location,\n            age=age,\n            phone=phone,\n        ) if name.strip() else []\n        pending = _pending_name_matches(db, candidate.disaster_id, name)\n\n        fuzzy_map = {person.id: score for person, score in fuzzy}\n        people = []\n        seen_ids: set[int] = set()\n        for person in exact + [person for person, _ in fuzzy]:\n            if person.id in seen_ids:\n                continue\n            seen_ids.add(person.id)\n            has_source = db.scalar(\n                select(Source.id).where(\n                    Source.person_id == person.id,\n                    Source.url == candidate.url,\n                )\n            ) is not None\n            people.append(\n                {\n                    "id": person.id,\n                    "case_number": person.case_number,\n                    "name": person.name,\n                    "age": person.age,\n                    "last_seen_location": person.last_seen_location,\n                    "score": 100.0 if person in exact else fuzzy_map.get(person.id, 0.0),\n                    "exact_name": person in exact,\n                    "source_already_attached": has_source,\n                }\n            )\n\n        return JSONResponse(\n            {\n                "people": people,\n                "pending": [\n                    {"id": item.id, "name": item.name}\n                    for item in pending[:5]\n                ],\n            }\n        )\n\n\n@router.get(\n    "/admin/discovery/{candidate_id}",\n    response_class=HTMLResponse,\n)\nasync def discovery_candidate_review(\n    request: Request,\n    candidate_id: int,\n    created: int | None = None,\n    attached: int | None = None,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n\n        source_image_url = None\n        source_post_text = ""\n        ocr_text = ""\n        ocr_detail = None\n\n        if candidate.platform == "facebook":\n            source_post_text = (await discover_public_post_text(candidate.url)) or ""\n            source_image_url = await discover_public_post_image(candidate.url)\n\n        if source_image_url:\n            if ocr_available():\n                ocr_dir = settings.upload_dir / "_ocr_preview"\n                ocr_filename = await download_public_source_image(\n                    source_image_url,\n                    ocr_dir,\n                )\n                if ocr_filename:\n                    local_path = ocr_dir / ocr_filename\n                    result = extract_ocr_text(local_path)\n                    ocr_text = result.text\n                    ocr_detail = result.detail\n                    try:\n                        local_path.unlink(missing_ok=True)\n                        ocr_dir.rmdir()\n                    except OSError:\n                        pass\n            else:\n                ocr_detail = (\n                    "Local OCR is not available yet. Install Tesseract OCR "\n                    "and the Nepali language data to read poster text automatically."\n                )\n\n        prefill = extract_candidate_prefill(\n            candidate,\n            disaster,\n            ocr_text=ocr_text,\n            source_text=source_post_text,\n        )\n        chatgpt_prefill_prompt = build_candidate_chatgpt_prefill_prompt(\n            disaster,\n            candidate,\n            source_post_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        detected_people = extract_candidate_people_names(\n            candidate,\n            source_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        multiple_people_signal = candidate_mentions_multiple_people(\n            candidate,\n            source_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        if prefill.get("name") and prefill["name"].casefold() not in {\n            item.casefold() for item in detected_people\n        }:\n            detected_people.insert(0, prefill["name"])\n\n        source_submission_names = {\n            (item or "").strip().casefold()\n            for item in db.scalars(\n                select(Submission.name).where(\n                    Submission.disaster_id == candidate.disaster_id,\n                    Submission.social_url == candidate.url,\n                    Submission.status != "rejected",\n                )\n            ).all()\n            if item\n        }\n        remaining_people = [\n            item for item in detected_people\n            if item.casefold() not in source_submission_names\n        ]\n\n        if (\n            created\n            and remaining_people\n            and str(prefill.get("name") or "").strip().casefold()\n            in source_submission_names\n        ):\n            # After one person is created from a multi-person source, move the\n            # review form to the next explicit name. Other fields remain review\n            # suggestions and must still be checked by the operator.\n            prefill["name"] = remaining_people[0]\n\n        exact_duplicates = _exact_name_matches(\n            db,\n            candidate.disaster_id,\n            str(prefill.get("name") or ""),\n        )\n        pending_duplicates = _pending_name_matches(\n            db,\n            candidate.disaster_id,\n            str(prefill.get("name") or ""),\n        )\n\n        db.commit()\n\n        return render(\n            request,\n            "admin_discovery_review.html",\n            candidate=candidate,\n            prefill=prefill,\n            source_image_url=source_image_url,\n            source_post_text=source_post_text,\n            ocr_text=ocr_text,\n            ocr_detail=ocr_detail,\n            detected_people=detected_people,\n            remaining_people=remaining_people,\n            multiple_people_signal=multiple_people_signal,\n            exact_duplicates=exact_duplicates,\n            pending_duplicates=pending_duplicates,\n            source_submission_names=source_submission_names,\n            chatgpt_prefill_prompt=chatgpt_prefill_prompt,\n            created=bool(created),\n            attached=bool(attached),\n        )\n\n\n@router.post("/admin/discovery/{candidate_id}/submission")\nasync def discovery_to_submission(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n        if candidate.status in {"irrelevant", "rejected"}:\n            return HTMLResponse(\n                "Restore this discovery candidate before creating a submission.",\n                status_code=409,\n            )\n\n        name = str(form.get("name") or "").strip()\n        location = str(form.get("last_seen_location") or "").strip()\n        if not name or not location:\n            return RedirectResponse(f"/admin/discovery/{candidate_id}", status_code=303)\n\n        ocr_text = str(form.get("ocr_text") or "").strip()\n        source_post_text = str(form.get("source_post_text") or "").strip()\n        notes_parts = []\n        if source_post_text:\n            notes_parts.append("Public post text:\\n" + source_post_text[:12_000])\n        elif candidate.snippet:\n            notes_parts.append("Search/public snippet:\\n" + candidate.snippet)\n        if ocr_text:\n            notes_parts.append("OCR text from reviewed source image:\\n" + ocr_text)\n        notes = "\\n\\n".join(part.strip() for part in notes_parts if part.strip()) or None\n\n        exact_duplicates = _exact_name_matches(db, candidate.disaster_id, name)\n        duplicate_action = str(form.get("duplicate_action") or "").strip().casefold()\n\n        if exact_duplicates:\n            if duplicate_action.startswith("attach:"):\n                try:\n                    person_id = int(duplicate_action.split(":", 1)[1])\n                except ValueError:\n                    return HTMLResponse("Invalid duplicate action", status_code=400)\n                person = next((item for item in exact_duplicates if item.id == person_id), None)\n                if person is None:\n                    return HTMLResponse("Duplicate target does not match this name", status_code=409)\n\n                existing_source = db.scalar(\n                    select(Source).where(\n                        Source.person_id == person.id,\n                        Source.url == candidate.url,\n                    )\n                )\n                if existing_source is None:\n                    db.add(\n                        Source(\n                            person_id=person.id,\n                            platform=candidate.platform,\n                            url=candidate.url,\n                            source_text=notes,\n                        )\n                    )\n                elif notes and not existing_source.source_text:\n                    existing_source.source_text = notes\n\n                candidate.status = "relevant"\n                audit(\n                    db,\n                    request,\n                    "attach_discovery_source_existing_person",\n                    "person",\n                    person.id,\n                    candidate.url,\n                )\n                db.commit()\n                return RedirectResponse(\n                    f"/admin/discovery/{candidate_id}?attached=1#person-entry-form",\n                    status_code=303,\n                )\n\n            if duplicate_action != "continue":\n                return HTMLResponse(\n                    "Duplicate name detected. Choose the existing person to attach this source, "\n                    "or explicitly confirm that this is a different person with the same name.",\n                    status_code=409,\n                )\n\n        pending_duplicates = _pending_name_matches(\n            db,\n            candidate.disaster_id,\n            name,\n        )\n        if pending_duplicates and duplicate_action != "continue":\n            return HTMLResponse(\n                "A pending submission already uses this name. Review the pending entry first, "\n                "or explicitly confirm that this should be a separate entry.",\n                status_code=409,\n            )\n\n        source_image_url = str(form.get("source_image_url") or "").strip()\n        include_source_image = str(form.get("include_source_image") or "") == "1"\n        photo_path = None\n\n        if include_source_image and source_image_url and is_allowed_public_image_url(source_image_url):\n            photo_path = await download_public_source_image(\n                source_image_url,\n                settings.upload_dir,\n            )\n\n        same_source_submissions = db.scalars(\n            select(Submission).where(\n                Submission.disaster_id == candidate.disaster_id,\n                Submission.social_url == candidate.url,\n                Submission.status != "rejected",\n            )\n        ).all()\n        existing_same_source = any(\n            (item.name or "").strip().casefold() == name.casefold()\n            for item in same_source_submissions\n        )\n        if existing_same_source:\n            return HTMLResponse(\n                "This person already has a submission from this exact public source.",\n                status_code=409,\n            )\n\n        sub = Submission(\n            disaster_id=candidate.disaster_id,\n            kind="missing_report",\n            name=name,\n            photo_path=photo_path,\n            name_ne=str(form.get("name_ne") or "").strip() or None,\n            age=parse_int(form.get("age")),\n            gender=_normalize_gender(form.get("gender")),\n            last_seen_date=parse_date(form.get("last_seen_date")),\n            last_seen_time=parse_time(form.get("last_seen_time")),\n            last_seen_location=location,\n            clothing=str(form.get("clothing") or "").strip() or None,\n            identification_details=str(form.get("identification_details") or "").strip() or None,\n            public_contact_number=str(form.get("public_contact_number") or "").strip() or None,\n            social_url=candidate.url,\n            notes=notes,\n        )\n        db.add(sub)\n\n        # Keep the source in Relevant until an operator explicitly marks the\n        # whole post processed. One post may contain several missing people.\n        candidate.status = "relevant"\n        db.flush()\n        audit(\n            db,\n            request,\n            "candidate_to_submission",\n            "submission",\n            sub.id,\n            candidate.url,\n        )\n        db.commit()\n\n    return RedirectResponse(\n        f"/admin/discovery/{candidate_id}?created=1#person-entry-form",\n        status_code=303,\n    )\n\n\n@router.get(\n    "/admin/ai-review",\n    response_class=HTMLResponse,\n)\ndef discovery_ai_review_page(\n    request: Request,\n    disaster_id: int,\n    platform: str = "facebook",\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        candidates = list(\n            db.scalars(\n                select(DiscoveryCandidate)\n                .where(\n                    DiscoveryCandidate.disaster_id\n                    == disaster.id,\n                    DiscoveryCandidate.platform\n                    == platform,\n                    DiscoveryCandidate.status.in_(\n                        ["new", "needs_ai", "relevant"]\n                    ),\n                )\n                .order_by(\n                    DiscoveryCandidate.found_at.desc()\n                )\n                .limit(100)\n            ).all()\n        )\n\n        prompt = build_free_ai_review_prompt(\n            disaster,\n            candidates,\n        )\n\n        return render(\n            request,\n            "admin_ai_review.html",\n            disaster=disaster,\n            platform=platform,\n            candidates=candidates,\n            prompt=prompt,\n        )\n\n\n@router.post(\n    "/admin/ai-review/import"\n)\nasync def discovery_ai_review_import(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    platform = str(\n        form.get("platform") or "facebook"\n    ).strip()\n\n    raw_result = str(\n        form.get("result_json") or ""\n    ).strip()\n\n    if not disaster_id or not raw_result:\n        return HTMLResponse(\n            "Missing AI review data",\n            status_code=400,\n        )\n\n    try:\n        results = parse_free_ai_review(\n            raw_result\n        )\n    except ValueError:\n        return HTMLResponse(\n            "Invalid AI review JSON. "\n            "Return to Free AI Review and paste "\n            "the JSON response exactly.",\n            status_code=400,\n        )\n\n    created = 0\n    rejected = 0\n    uncertain = 0\n\n    downloaded_images: dict[str, str | None] = {}\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        for result in results:\n            candidate = db.get(\n                DiscoveryCandidate,\n                result["candidate_id"],\n            )\n\n            # AI output never gets authority to change\n            # disaster/source identity.\n            if candidate is None:\n                continue\n\n            if (\n                candidate.disaster_id\n                != disaster.id\n            ):\n                continue\n\n            if candidate.platform != platform:\n                continue\n\n            if candidate.status not in {\n                "new",\n                "needs_ai",\n                "relevant",\n            }:\n                continue\n\n            decision = result["decision"]\n\n            if decision == "reject":\n                candidate.status = "irrelevant"\n                rejected += 1\n                continue\n\n            if decision == "uncertain":\n                uncertain += 1\n                continue\n\n            accepted_person = False\n\n            for person_data in result["people"]:\n                name = str(\n                    person_data.get("name")\n                    or ""\n                ).strip()\n\n                if not name:\n                    continue\n\n                accepted_person = True\n\n                existing = db.scalar(\n                    select(Submission.id).where(\n                        Submission.disaster_id\n                        == disaster.id,\n                        Submission.social_url\n                        == candidate.url,\n                        Submission.name\n                        == name,\n                    )\n                )\n\n                if existing:\n                    continue\n\n                image_url = str(\n                    person_data.get(\n                        "image_url"\n                    )\n                    or ""\n                ).strip()\n\n                photo_path = None\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    if (\n                        image_url\n                        not in downloaded_images\n                    ):\n                        downloaded_images[\n                            image_url\n                        ] = (\n                            await download_public_source_image(\n                                image_url,\n                                settings.upload_dir,\n                            )\n                        )\n\n                    photo_path = (\n                        downloaded_images[\n                            image_url\n                        ]\n                    )\n\n                reason = result.get(\n                    "reason"\n                ) or ""\n\n                confidence = result.get(\n                    "confidence"\n                )\n\n                notes = (\n                    candidate.snippet\n                    or ""\n                ).strip()\n\n                ai_note = (\n                    f"Free AI review: {reason}"\n                )\n\n                if confidence is not None:\n                    ai_note += (\n                        f" | confidence={confidence}"\n                    )\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    ai_note += (\n                        f" | source_image_url={image_url}"\n                    )\n\n                if notes:\n                    notes = (\n                        notes\n                        + "\\n\\n"\n                        + ai_note\n                    )\n                else:\n                    notes = ai_note\n\n                submission = Submission(\n                    disaster_id=disaster.id,\n                    kind="missing_report",\n                    name=name,\n                    photo_path=photo_path,\n                    name_ne=(\n                        str(\n                            person_data.get(\n                                "name_ne"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    age=parse_int(\n                        person_data.get("age")\n                    ),\n                    gender=_normalize_gender(person_data.get("gender")),\n                    last_seen_date=parse_date(\n                        person_data.get(\n                            "last_seen_date"\n                        )\n                    ),\n                    last_seen_time=parse_time(\n                        person_data.get(\n                            "last_seen_time"\n                        )\n                    ),\n                    last_seen_location=(\n                        str(\n                            person_data.get(\n                                "last_seen_location"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    clothing=(\n                        str(\n                            person_data.get(\n                                "clothing"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    identification_details=(\n                        str(\n                            person_data.get(\n                                "identification_details"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    public_contact_number=(\n                        str(\n                            person_data.get(\n                                "public_contact_number"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    social_url=candidate.url,\n                    notes=notes,\n                )\n\n                db.add(submission)\n                created += 1\n\n            if accepted_person:\n                candidate.status = "reviewed"\n\n        audit(\n            db,\n            request,\n            "import_free_ai_review",\n            "disaster",\n            disaster.id,\n            (\n                f"platform={platform}; "\n                f"submissions={created}; "\n                f"rejected={rejected}; "\n                f"uncertain={uncertain}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.get("/admin/export", response_class=HTMLResponse)\ndef export_page(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_export.html", disasters=disasters)\n\n\n@router.get("/admin/export/{file_type}")\ndef export_data(request: Request, file_type: str, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if file_type not in {"csv", "xlsx"}:\n        return HTMLResponse("Unsupported export", status_code=400)\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n        if file_type == "csv":\n            data = build_csv(db, disaster_id)\n            media = "text/csv; charset=utf-8"\n        else:\n            data = build_xlsx(db, disaster_id)\n            media = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"\n        audit(db, request, "export", "disaster", disaster_id, file_type)\n        db.commit()\n        filename = f"{disaster.code.lower()}-missing-people.{file_type}"\n        return Response(\n            data,\n            media_type=media,\n            headers={"Content-Disposition": f\'attachment; filename="{filename}"\'},\n        )\n\n\n@router.get("/admin/people/{person_id}/share-card")\ndef share_card(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        image = build_share_card(person)\n        audit(db, request, "generate_share_card", "person", person.id)\n        db.commit()\n        return Response(\n            image,\n            media_type="image/png",\n            headers={"Content-Disposition": f\'inline; filename="{person.case_number}.png"\'},\n        )\n', 'app/templates/admin_discovery.html': '{% extends "base.html" %}\n{% block content %}\n\n<h1>Public Social Discovery</h1>\n\n<p class="muted">\n  V0 searches public web indexes only. It never logs into Facebook or accesses\n  closed/private groups. Every result remains subject to admin review.\n</p>\n\n<form method="get" class="card inline">\n  <div>\n    <label>Event</label>\n    <select name="disaster_id">\n      {% for d in disasters %}\n      <option value="{{ d.id }}" {% if selected and selected.id == d.id %}selected{% endif %}>\n        {{ d.name }}\n      </option>\n      {% endfor %}\n    </select>\n  </div>\n\n  <div>\n    <label>Platform</label>\n    <select name="platform">\n      {% for p in [\'facebook\',\'web\',\'instagram\',\'tiktok\',\'x\',\'reddit\'] %}\n      <option value="{{ p }}" {% if platform == p %}selected{% endif %}>{{ p }}</option>\n      {% endfor %}\n    </select>\n  </div>\n\n  <input type="hidden" name="view" value="{{ view }}">\n\n  <div>\n    <button>Load Discovery</button>\n  </div>\n</form>\n\n{% if selected %}\n\n{% if wide_error %}\n<div class="notice">\n  <strong>Wide Discovery could not run.</strong><br>\n  The configured Serper / Google Search provider is unavailable, rejected, or\n  has reached its quota.\n</div>\n{% endif %}\n\n{% if wide_stats %}\n<div class="notice">\n  <strong>Wide Discovery finished</strong><br>\n  Queries searched: {{ wide_stats.queries }}<br>\n  Raw search results: {{ wide_stats.raw }}<br>\n  New candidates sent to review: {{ wide_stats.added }}\n</div>\n{% endif %}\n\n<div class="card">\n  <h2>Findings queue</h2>\n  <p class="muted">\n    Relevant and irrelevant decisions are retained. Nothing is deleted, so an\n    administrator can restore a result later if it was classified incorrectly.\n  </p>\n\n  <div class="inline" style="gap:8px; flex-wrap:wrap">\n    <a href="{{ queue_links.review }}">To Review ({{ queue_counts.review }})</a>\n    <a href="{{ queue_links.relevant }}">Relevant ({{ queue_counts.relevant }})</a>\n    <a href="{{ queue_links.irrelevant }}">Irrelevant ({{ queue_counts.irrelevant }})</a>\n    <a href="{{ queue_links.processed }}">Processed ({{ queue_counts.processed }})</a>\n  </div>\n</div>\n\n<form method="get" class="card inline">\n  <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n  <input type="hidden" name="platform" value="{{ platform }}">\n  <input type="hidden" name="view" value="{{ view }}">\n\n  <div style="min-width:320px; flex:1">\n    <label>Search findings by person name</label>\n    <input\n      name="q"\n      value="{{ q }}"\n      placeholder="Name in English or Nepali"\n      autocomplete="off"\n    >\n  </div>\n\n  <div>\n    <button>Search Findings</button>\n  </div>\n\n  {% if q %}\n  <div>\n    <a href="{{ clear_search_url }}">Clear search</a>\n  </div>\n  {% endif %}\n</form>\n\n<div class="grid">\n  <div class="card">\n    <h2>Automated Discovery</h2>\n    <p>Runs the bounded public-web discovery collector and person-level filters.</p>\n    <form method="post" action="/admin/discovery/run">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <button>Run Discovery Bot</button>\n    </form>\n  </div>\n\n  {% if platform == \'facebook\' %}\n  <div class="card">\n    <h2>Wide Discovery</h2>\n    <p>\n      Person-focused Facebook discovery using affected places, stronger\n      missing-person phrases, the event date window, and human-confirmed\n      productive sources.\n    </p>\n\n    <p>\n      <strong>Provider:</strong> {{ wide_provider_status.name }} —\n      {% if wide_provider_status.available %}\n        <span class="badge">READY</span>\n      {% else %}\n        <span class="badge">NOT CONFIGURED</span>\n      {% endif %}\n    </p>\n\n    <p class="muted">{{ wide_provider_status.detail }}</p>\n\n    {% if wide_provider_status.available %}\n    <form method="post" action="/admin/wide-discovery/run">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <button>Run Wide Discovery</button>\n    </form>\n    {% else %}\n    <button disabled>Run Wide Discovery</button>\n    <p class="muted">Set SERPER_API_KEY in the server environment to enable it.</p>\n    {% endif %}\n\n    <p class="muted">\n      A run uses at most 40 search queries. Avoid repeating it unnecessarily.\n    </p>\n\n    <details style="margin-top:12px">\n      <summary>Show Wide Search Plan ({{ wide_query_plan|length }} queries)</summary>\n      <div style="max-height:420px; overflow:auto; margin-top:10px">\n        {% for query in wide_query_plan %}\n        <p><strong>{{ \'%03d\'|format(loop.index) }}.</strong> <code>{{ query }}</code></p>\n        {% else %}\n        <p>No wide queries generated.</p>\n        {% endfor %}\n      </div>\n    </details>\n  </div>\n  {% endif %}\n\n  <div class="card">\n    <h2>Free AI Review</h2>\n    <p>\n      Review collected candidates using a free interactive AI session. No AI\n      API call is made.\n    </p>\n    <form method="get" action="/admin/ai-review">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <button>Prepare Free AI Review</button>\n    </form>\n  </div>\n\n  <div class="card" id="manual-intake">\n    <h2>Manual Finding Intake</h2>\n    <p class="muted">\n      Use this when a targeted search finds a public post that automated\n      discovery missed, or when you need to add fuller public text/context to\n      an existing candidate.\n    </p>\n    <form method="post" action="/admin/discovery/manual">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n\n      <label>Search / source context</label>\n      <input\n        id="manual-search-query"\n        name="search_query"\n        placeholder="Optional: the targeted query or source that found this post"\n      >\n\n      <label>Public source URL *</label>\n      <input id="manual-source-url" type="url" name="url" required>\n\n      <label>Title</label>\n      <input name="title">\n\n      <label>Full public post text / additional context</label>\n      <textarea\n        name="snippet"\n        rows="8"\n        placeholder="Paste the public caption, poster text, contact details, names, or other useful context that the automated search result missed."\n      ></textarea>\n\n      <button>Add / Enrich Candidate</button>\n    </form>\n  </div>\n</div>\n\n{% if platform == \'facebook\' and priority_searches %}\n<details style="margin-top:18px" open>\n  <summary>Priority missing-person sharers</summary>\n  <div class="card">\n    <p class="muted">\n      These are public sources currently observed sharing person-level\n      Rasuwa missing-person information. They are search seeds only. Every\n      post still requires person-level filtering and human review.\n    </p>\n\n    {% for item in priority_searches %}\n    <div style="padding:10px 0; border-bottom:1px solid #ddd">\n      <strong>{{ item.label }}</strong>\n      {% if item.tier == \'high\' %}\n      <span class="badge">HIGH ACTIVITY</span>\n      {% endif %}\n      <br>\n\n      <a href="{{ item.url }}" target="_blank" rel="noopener noreferrer">\n        Search this source\n      </a>\n\n      {% if item.source_url %}\n      &nbsp; | &nbsp;\n      <a href="{{ item.source_url }}" target="_blank" rel="noopener noreferrer">\n        Open source page\n      </a>\n      {% endif %}\n\n      &nbsp;\n      <button\n        type="button"\n        class="manual-add-query"\n        data-query="{{ item.query|e }}"\n      >Manual Add</button>\n\n      <div style="margin-top:6px">\n        <code>{{ item.query }}</code>\n      </div>\n    </div>\n    {% endfor %}\n  </div>\n</details>\n{% endif %}\n\n<details style="margin-top:18px">\n  <summary>Targeted manual searches</summary>\n  <div class="card">\n    <p class="muted">\n      If a search result is useful but automation did not collect it, click\n      Manual Add. The intake form will remember which query found it.\n    </p>\n\n    {% for query, url in queries %}\n    <p>\n      <a href="{{ url }}" target="_blank" rel="noopener noreferrer">Search</a>\n      &nbsp;\n      <button\n        type="button"\n        class="manual-add-query"\n        data-query="{{ query|e }}"\n      >Manual Add</button>\n      <br>\n      <code>{{ query }}</code>\n    </p>\n    {% else %}\n    <p>No queries.</p>\n    {% endfor %}\n  </div>\n</details>\n\n<h2>\n  {% if view == \'review\' %}To Review{% elif view == \'relevant\' %}Relevant Findings{% elif view == \'irrelevant\' %}Irrelevant Archive{% else %}Processed Findings{% endif %}\n</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Platform</th>\n      <th>Candidate</th>\n      <th>Status</th>\n      <th>Review</th>\n      <th>Classification</th>\n    </tr>\n  </thead>\n  <tbody>\n    {% for c in candidates %}\n    <tr id="candidate-{{ c.id }}">\n      <td>{{ c.platform }}</td>\n      <td>\n        <a href="{{ c.url }}" target="_blank" rel="noopener noreferrer">\n          {{ c.title or c.url }}\n        </a>\n\n        <div\n          class="candidate-public-details"\n          data-candidate-id="{{ c.id }}"\n          style="margin-top:10px"\n        >\n          <div class="muted" style="white-space:pre-wrap">\n            <strong>Search/public text:</strong>\n            <span class="candidate-text">{{ c.snippet or \'No text supplied by search provider.\' }}</span>\n          </div>\n          <div class="candidate-structured" style="margin-top:8px"></div>\n          {% if c.platform == \'facebook\' %}\n          <div class="candidate-load-status muted" style="margin-top:6px">\n            Loading richer public post details when available…\n          </div>\n          {% endif %}\n        </div>\n      </td>\n      <td>{{ c.status }}</td>\n      <td><a class="discovery-review-link" href="/admin/discovery/{{ c.id }}">Review Details</a></td>\n      <td>\n        {% if c.status in [\'new\', \'needs_ai\'] %}\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="relevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button>✓ Relevant</button>\n        </form>\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="irrelevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button class="secondary">Not relevant</button>\n        </form>\n        {% elif c.status == \'relevant\' %}\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="irrelevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button class="secondary">Move to Irrelevant</button>\n        </form>\n        {% elif c.status in [\'irrelevant\', \'rejected\'] %}\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="restore">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button>Restore to Review</button>\n        </form>\n        {% else %}\n        <span class="muted">Already processed</span>\n        {% endif %}\n      </td>\n    </tr>\n    {% else %}\n    <tr>\n      <td colspan="5">No findings in this section.</td>\n    </tr>\n    {% endfor %}\n  </tbody>\n</table>\n\n{% endif %}\n\n<script>\n(function () {\n  const blocks = Array.from(document.querySelectorAll(\'.candidate-public-details\'));\n  const scrollKey = `mp-discovery-scroll:${location.pathname}${location.search}`;\n\n  const savedScroll = sessionStorage.getItem(scrollKey);\n  if (savedScroll !== null) {\n    sessionStorage.removeItem(scrollKey);\n    const y = Number(savedScroll);\n    if (Number.isFinite(y)) {\n      requestAnimationFrame(() => window.scrollTo(0, y));\n    }\n  }\n\n  function rememberDiscoveryPosition() {\n    sessionStorage.setItem(scrollKey, String(window.scrollY));\n  }\n\n  document.querySelectorAll(\'.discovery-status-form\').forEach((form) => {\n    form.addEventListener(\'submit\', rememberDiscoveryPosition);\n  });\n\n  document.querySelectorAll(\'.discovery-review-link\').forEach((link) => {\n    link.addEventListener(\'click\', rememberDiscoveryPosition);\n  });\n\n  document.querySelectorAll(\'.manual-add-query\').forEach((button) => {\n    button.addEventListener(\'click\', () => {\n      const queryInput = document.getElementById(\'manual-search-query\');\n      const urlInput = document.getElementById(\'manual-source-url\');\n      const intake = document.getElementById(\'manual-intake\');\n\n      if (queryInput) {\n        queryInput.value = button.dataset.query || \'\';\n      }\n\n      if (intake) {\n        intake.scrollIntoView({behavior: \'smooth\', block: \'start\'});\n      }\n\n      if (urlInput) {\n        window.setTimeout(() => urlInput.focus(), 250);\n      }\n    });\n  });\n\n  async function loadDetails(block) {\n    if (block.dataset.loaded === \'1\') return;\n    block.dataset.loaded = \'1\';\n\n    const id = block.dataset.candidateId;\n    const status = block.querySelector(\'.candidate-load-status\');\n    if (!status) return;\n\n    try {\n      const response = await fetch(`/admin/discovery/${id}/public-details`, {\n        credentials: \'same-origin\'\n      });\n      if (!response.ok) throw new Error(\'details unavailable\');\n      const data = await response.json();\n\n      const text = block.querySelector(\'.candidate-text\');\n      if (data.text && text) text.textContent = data.text;\n\n      const structured = block.querySelector(\'.candidate-structured\');\n      const parts = [];\n      if (data.multiple_people) {\n        parts.push(\'<strong>⚠ Multiple people may be reported in this post</strong>\');\n      }\n      if (Array.isArray(data.people) && data.people.length) {\n        parts.push(`<strong>Possible person(s):</strong> ${data.people.map(escapeHtml).join(\', \')}`);\n      }\n      if (data.age) parts.push(`<strong>Age:</strong> ${escapeHtml(String(data.age))}`);\n      if (data.last_seen_location) {\n        parts.push(`<strong>Last seen:</strong> ${escapeHtml(data.last_seen_location)}`);\n      }\n      if (data.public_contact_number) {\n        parts.push(`<strong>Public contact:</strong> ${escapeHtml(data.public_contact_number)}`);\n      }\n      structured.innerHTML = parts.join(\' &nbsp; | &nbsp; \');\n\n      status.textContent = data.full_public_text_available\n        ? \'Fuller public post text loaded into this page.\'\n        : \'Facebook did not expose fuller public text. Showing the best indexed text available.\';\n    } catch (error) {\n      status.textContent = \'Could not load more public text. Showing the indexed search text.\';\n    }\n  }\n\n  function escapeHtml(value) {\n    const div = document.createElement(\'div\');\n    div.textContent = value == null ? \'\' : String(value);\n    return div.innerHTML;\n  }\n\n  if (\'IntersectionObserver\' in window) {\n    const observer = new IntersectionObserver((entries) => {\n      for (const entry of entries) {\n        if (entry.isIntersecting) {\n          loadDetails(entry.target);\n          observer.unobserve(entry.target);\n        }\n      }\n    }, {rootMargin: \'250px\'});\n    blocks.forEach((block) => observer.observe(block));\n  } else {\n    blocks.forEach(loadDetails);\n  }\n})();\n</script>\n\n{% endblock %}\n', 'app/services/wide_discovery.py': 'from __future__ import annotations\n\nimport time\nfrom datetime import timedelta\nfrom typing import Protocol\nfrom urllib.parse import urlparse\n\nimport httpx\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom ..models import Disaster, DiscoveryCandidate\nfrom .discovery import SearchResult, is_person_specific_candidate\nfrom .normalization import canonicalize_url\nfrom .priority_sources import priority_source_scopes, priority_wide_queries\nfrom .search_providers import SerperPublicSearch\n\n\nclass SearchProvider(Protocol):\n    def search(\n        self,\n        query: str,\n        max_results: int = 15,\n    ) -> list[SearchResult]:\n        ...\n\n\nWIDE_MAX_QUERIES = 40\nWIDE_RESULTS_PER_QUERY = 15\nWIDE_REQUEST_DELAY_SECONDS = 0.40\n\n\nPRECISION_TERMS = [\n    "out of contact",\n    "last seen",\n    "has been missing",\n    "person missing",\n    "cannot be contacted",\n    "सम्पर्कविहीन",\n    "सम्पर्क विहीन",\n    "बेपत्ता",\n    "खोजिदिनुहोला",\n    "हराएको व्यक्ति",\n]\n\nLIST_TERMS = [\n    "missing persons list",\n    "missing people names",\n    "named missing people",\n    "missing family",\n    "बेपत्ता नामावली",\n    "सम्पर्कविहीन नाम",\n    "हराएका व्यक्तिको सूची",\n]\n\nSOURCE_TERMS = [\n    "out of contact",\n    "last seen",\n    "person missing",\n    "सम्पर्कविहीन",\n    "बेपत्ता",\n    "खोजिदिनुहोला",\n]\n\n\ndef is_facebook_post_url(url: str) -> bool:\n    try:\n        parsed = urlparse(url)\n    except ValueError:\n        return False\n\n    host = (parsed.hostname or "").casefold()\n    if not (host == "facebook.com" or host.endswith(".facebook.com")):\n        return False\n\n    path = parsed.path.casefold()\n    return (\n        "/posts/" in path\n        or "/groups/" in path and "/posts/" in path\n        or "permalink.php" in path\n        or "story.php" in path\n        or "/photos/" in path\n        or "/photo/" in path\n        or "/reel/" in path\n        or "/reels/" in path\n        or "/share/p/" in path\n        or "/share/v/" in path\n    )\n\n\ndef facebook_source_scope(url: str) -> str | None:\n    try:\n        parsed = urlparse(url)\n    except ValueError:\n        return None\n\n    host = (parsed.hostname or "").casefold()\n    if not (host == "facebook.com" or host.endswith(".facebook.com")):\n        return None\n\n    parts = [part for part in parsed.path.split("/") if part]\n    if not parts:\n        return None\n\n    if parts[0].casefold() == "groups" and len(parts) >= 2:\n        return f"groups/{parts[1]}"\n\n    blocked = {\n        "watch", "reel", "reels", "photo", "photos", "share",\n        "story.php", "permalink.php",\n    }\n    if parts[0].casefold() in blocked:\n        return None\n\n    return parts[0]\n\n\ndef _unique(items: list[str]) -> list[str]:\n    output: list[str] = []\n    seen: set[str] = set()\n    for item in items:\n        normalized = " ".join(item.split())\n        if not normalized or normalized in seen:\n            continue\n        seen.add(normalized)\n        output.append(normalized)\n    return output\n\n\ndef _round_robin(groups: list[list[str]], max_queries: int) -> list[str]:\n    indexes = [0 for _ in groups]\n    output: list[str] = []\n    seen: set[str] = set()\n\n    while len(output) < max_queries:\n        added = False\n        for group_index, group in enumerate(groups):\n            while indexes[group_index] < len(group):\n                query = group[indexes[group_index]]\n                indexes[group_index] += 1\n                if query in seen:\n                    continue\n                seen.add(query)\n                output.append(query)\n                added = True\n                break\n            if len(output) >= max_queries:\n                break\n        if not added:\n            break\n\n    return output\n\n\ndef generate_wide_queries(\n    disaster: Disaster,\n    source_scopes: list[str] | None = None,\n    max_queries: int = WIDE_MAX_QUERIES,\n) -> list[str]:\n    """Generate a bounded, person-focused Facebook search plan.\n\n    Broad standalone ``missing`` searches are intentionally excluded. Every\n    query is constrained to Facebook, an event/location, a stronger\n    missing-person phrase, and the disaster time window.\n    """\n    locations = disaster.locations()\n    search_places = _unique([disaster.name, *locations])\n    event_root = (\n        disaster.name.replace("Flood", "").replace("flood", "").strip()\n        or disaster.name\n    )\n    after = (disaster.start_date - timedelta(days=1)).isoformat()\n    date_filter = f"after:{after}"\n\n    location_queries: list[str] = []\n    for place in search_places:\n        for term in PRECISION_TERMS:\n            location_queries.append(\n                f\'site:facebook.com "{place}" "{term}" {date_filter}\'\n            )\n\n    list_queries: list[str] = []\n    for term in LIST_TERMS:\n        list_queries.append(\n            f\'site:facebook.com "{event_root}" "{term}" {date_filter}\'\n        )\n\n    priority_queries = priority_wide_queries(disaster)\n\n    source_queries: list[str] = []\n    # Research-backed seed sources and human-confirmed productive sources get\n    # reserved space. Human-learned scopes remain event-specific.\n    seeded_scopes = priority_source_scopes()\n    combined_scopes = _unique([*seeded_scopes, *(source_scopes or [])])\n\n    for scope in combined_scopes:\n        for term in SOURCE_TERMS:\n            source_queries.append(\n                f\'site:facebook.com/{scope} "{event_root}" "{term}" {date_filter}\'\n            )\n        for place in locations[:4]:\n            for term in ("out of contact", "सम्पर्कविहीन", "बेपत्ता"):\n                source_queries.append(\n                    f\'site:facebook.com/{scope} "{place}" "{term}" {date_filter}\'\n                )\n\n    location_queries = _unique(location_queries)\n    list_queries = _unique(list_queries)\n    source_queries = _unique(source_queries)\n    priority_queries = _unique(priority_queries)\n\n    # Priority source seeds receive a guaranteed lane, while location results\n    # still dominate the bounded plan. The hard cap is never exceeded.\n    return _round_robin(\n        [\n            priority_queries,\n            location_queries,\n            source_queries,\n            location_queries,\n            list_queries,\n        ],\n        max_queries,\n    )\n\n\ndef collect_known_source_scopes(\n    db: Session,\n    disaster_id: int,\n    limit: int = 30,\n) -> list[str]:\n    """Return source scopes promoted by human/processed relevance.\n\n    Repeated relevant posts rank ahead of one-off sources. This lets the\n    discovery engine learn new high-output sharers without trusting raw,\n    unreviewed search results.\n    """\n    urls = list(\n        db.scalars(\n            select(DiscoveryCandidate.url)\n            .where(\n                DiscoveryCandidate.disaster_id == disaster_id,\n                DiscoveryCandidate.status.in_(["relevant", "reviewed"]),\n            )\n            .order_by(DiscoveryCandidate.found_at.desc())\n            .limit(1000)\n        ).all()\n    )\n\n    counts: dict[str, int] = {}\n    first_seen: dict[str, int] = {}\n\n    for index, url in enumerate(urls):\n        scope = facebook_source_scope(url)\n        if not scope:\n            continue\n        counts[scope] = counts.get(scope, 0) + 1\n        first_seen.setdefault(scope, index)\n\n    ranked = sorted(\n        counts,\n        key=lambda scope: (\n            -counts[scope],\n            first_seen[scope],\n            scope.casefold(),\n        ),\n    )\n    return ranked[:limit]\n\n\ndef _is_source_scoped_query(query: str) -> bool:\n    prefix = "site:facebook.com/"\n    return query.casefold().startswith(prefix) and not query.casefold().startswith(\n        "site:facebook.com \\"")\n\n\ndef run_wide_discovery(\n    db: Session,\n    disaster: Disaster,\n    provider: SearchProvider | None = None,\n    max_queries: int = WIDE_MAX_QUERIES,\n    request_delay_seconds: float = WIDE_REQUEST_DELAY_SECONDS,\n) -> dict[str, int]:\n    provider = provider or SerperPublicSearch()\n\n    scopes = collect_known_source_scopes(db, disaster.id)\n    queries = generate_wide_queries(\n        disaster,\n        source_scopes=scopes,\n        max_queries=max_queries,\n    )\n\n    searched = 0\n    raw_results = 0\n    accepted_for_ai = 0\n    seen_urls: set[str] = set()\n\n    for index, query in enumerate(queries):\n        searched += 1\n        try:\n            results = provider.search(\n                query,\n                max_results=WIDE_RESULTS_PER_QUERY,\n            )\n        except httpx.HTTPError:\n            continue\n\n        for result in results:\n            raw_results += 1\n            url = canonicalize_url(result.url)\n            if not url or url in seen_urls:\n                continue\n            seen_urls.add(url)\n\n            if not is_facebook_post_url(url):\n                continue\n\n            normalized_result = SearchResult(\n                url=url,\n                title=result.title,\n                snippet=result.snippet,\n            )\n\n            # Normal searches require explicit event context in the indexed\n            # text. Human-confirmed source sweeps may omit it, but still need\n            # strong person-level evidence.\n            if not is_person_specific_candidate(\n                normalized_result,\n                disaster,\n                require_event_context=not _is_source_scoped_query(query),\n            ):\n                continue\n\n            existing = db.scalar(\n                select(DiscoveryCandidate.id).where(\n                    DiscoveryCandidate.disaster_id == disaster.id,\n                    DiscoveryCandidate.url == url,\n                )\n            )\n            if existing:\n                continue\n\n            db.add(\n                DiscoveryCandidate(\n                    disaster_id=disaster.id,\n                    platform="facebook",\n                    query="wide:" + query,\n                    url=url,\n                    title=result.title,\n                    snippet=result.snippet,\n                    status="needs_ai",\n                )\n            )\n            accepted_for_ai += 1\n\n        if request_delay_seconds > 0 and index < len(queries) - 1:\n            time.sleep(request_delay_seconds)\n\n    return {\n        "queries": searched,\n        "raw_results": raw_results,\n        "needs_ai": accepted_for_ai,\n    }\n', 'app/services/priority_sources.py': 'from __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import timedelta\n\nfrom ..models import Disaster\n\n\n@dataclass(frozen=True)\nclass PrioritySource:\n    label: str\n    facebook_scope: str | None = None\n    tier: str = "monitored"\n\n\n# Public sources observed sharing person-level Rasuwa flood missing-person\n# information. These are search seeds only. Their posts still pass the same\n# person-level filters and human review as every other source.\nPRIORITY_SOURCES: tuple[PrioritySource, ...] = (\n    PrioritySource(\n        "Saigrace Pokharel / Saigrace Official",\n        "saigraceofficial",\n        "high",\n    ),\n    PrioritySource(\n        "Bikki Gurung",\n        "Bikkigurungofficial",\n        "high",\n    ),\n    PrioritySource(\n        "Hydropower Diaries",\n        None,\n        "high",\n    ),\n    PrioritySource(\n        "Medico Nepal",\n        "MedicoNepalOfficial",\n        "high",\n    ),\n    PrioritySource(\n        "Engineers Vlogs",\n        None,\n        "monitored",\n    ),\n    PrioritySource(\n        "Hamro Sharemarket",\n        "hamrosharemarketofficial",\n        "monitored",\n    ),\n    PrioritySource(\n        "LoL NEPAL",\n        None,\n        "monitored",\n    ),\n    PrioritySource(\n        "इन्जिनियरको ब्यथा अरुलाई के था",\n        None,\n        "monitored",\n    ),\n)\n\n\ndef _event_root(disaster: Disaster) -> str:\n    return (\n        disaster.name\n        .replace("Flood", "")\n        .replace("flood", "")\n        .strip()\n        or disaster.name\n    )\n\n\ndef _source_prefix(source: PrioritySource) -> str:\n    if source.facebook_scope:\n        return f"site:facebook.com/{source.facebook_scope}"\n    return f\'site:facebook.com "{source.label}"\'\n\n\ndef priority_manual_searches(\n    disaster: Disaster,\n) -> list[dict[str, str]]:\n    """Queries shown to an operator for one-click manual investigation.\n\n    Manual searches are intentionally a little broader than automated\n    admission because a human is deciding what to add.\n    """\n    event_root = _event_root(disaster)\n    locations = disaster.locations()\n    top_location = locations[0] if locations else event_root\n\n    rows: list[dict[str, str]] = []\n    for source in PRIORITY_SOURCES:\n        prefix = _source_prefix(source)\n\n        for query in (\n            f\'{prefix} "{event_root}" "missing"\',\n            f\'{prefix} "{top_location}" "out of contact"\',\n        ):\n            rows.append(\n                {\n                    "label": source.label,\n                    "tier": source.tier,\n                    "query": " ".join(query.split()),\n                    "source_url": (\n                        f"https://www.facebook.com/{source.facebook_scope}/"\n                        if source.facebook_scope\n                        else ""\n                    ),\n                }\n            )\n\n    return rows\n\n\ndef priority_wide_queries(\n    disaster: Disaster,\n) -> list[str]:\n    """Reserved high-value source queries for automated Serper discovery."""\n    event_root = _event_root(disaster)\n    after = (disaster.start_date - timedelta(days=1)).isoformat()\n    date_filter = f"after:{after}"\n\n    queries: list[str] = []\n\n    # One query per source keeps this lane useful without swallowing the\n    # 40-query global budget.\n    for source in PRIORITY_SOURCES:\n        prefix = _source_prefix(source)\n        queries.append(\n            " ".join(\n                f\'{prefix} "{event_root}" "missing person" {date_filter}\'.split()\n            )\n        )\n\n    return queries\n\n\ndef priority_source_scopes() -> list[str]:\n    """Known Facebook scopes that can safely receive source-scoped searches."""\n    return [\n        source.facebook_scope\n        for source in PRIORITY_SOURCES\n        if source.facebook_scope\n    ]\n', 'tests/test_priority_source_manual_intake_upgrade.py': 'from datetime import date\n\nfrom app.database import SessionLocal\nfrom app.models import Disaster, DiscoveryCandidate\nfrom app.services.priority_sources import (\n    PRIORITY_SOURCES,\n    priority_manual_searches,\n)\nfrom app.services.wide_discovery import (\n    collect_known_source_scopes,\n    generate_wide_queries,\n)\n\n\ndef event():\n    return Disaster(\n        code="RF",\n        name="Rasuwa Flood",\n        disaster_type="flood",\n        start_date=date(2026, 8, 26),\n        affected_locations="Rasuwa\\nTimure\\nBetrawati",\n    )\n\n\ndef create_event(client):\n    response = client.post(\n        "/admin/events",\n        data={\n            "code": "RF",\n            "name": "Rasuwa Flood",\n            "disaster_type": "flood",\n            "start_date": "2026-08-26",\n            "affected_locations": "Rasuwa\\nTimure\\nBetrawati",\n            "active": "on",\n        },\n        follow_redirects=False,\n    )\n    assert response.status_code == 303\n\n\ndef test_priority_seed_sources_include_current_high_value_sharers():\n    labels = {source.label for source in PRIORITY_SOURCES}\n    assert "Saigrace Pokharel / Saigrace Official" in labels\n    assert "Bikki Gurung" in labels\n    assert "Hydropower Diaries" in labels\n    assert "Medico Nepal" in labels\n\n\ndef test_priority_manual_searches_are_facebook_and_event_scoped():\n    rows = priority_manual_searches(event())\n    assert rows\n    assert all("site:facebook.com" in row["query"] for row in rows)\n    assert all(\n        "Rasuwa" in row["query"] or "Timure" in row["query"]\n        for row in rows\n    )\n    assert any("saigraceofficial" in row["query"].casefold() for row in rows)\n    assert any("Hydropower Diaries" in row["query"] for row in rows)\n\n\ndef test_wide_plan_reserves_priority_source_lane():\n    queries = generate_wide_queries(event(), source_scopes=[])\n    folded = "\\n".join(queries).casefold()\n    assert "saigraceofficial" in folded\n    assert "bikkigurungofficial" in folded\n    assert "hydropower diaries" in folded\n    assert all("after:2026-08-25" in query for query in queries)\n\n\ndef test_repeat_relevant_source_ranks_before_one_off_source():\n    with SessionLocal() as db:\n        disaster = Disaster(\n            code="RF",\n            name="Rasuwa Flood",\n            disaster_type="flood",\n            start_date=date(2026, 8, 26),\n            affected_locations="Rasuwa\\nTimure",\n            active=True,\n        )\n        db.add(disaster)\n        db.flush()\n\n        rows = [\n            ("https://facebook.com/repeater/posts/1", "relevant"),\n            ("https://facebook.com/oneoff/posts/1", "relevant"),\n            ("https://facebook.com/repeater/posts/2", "reviewed"),\n        ]\n        for url, status in rows:\n            db.add(\n                DiscoveryCandidate(\n                    disaster_id=disaster.id,\n                    platform="facebook",\n                    query="test",\n                    url=url,\n                    title="Person missing",\n                    snippet="Named person out of contact in Timure",\n                    status=status,\n                )\n            )\n        db.commit()\n\n        scopes = collect_known_source_scopes(db, disaster.id)\n\n    assert scopes[0] == "repeater"\n    assert "oneoff" in scopes\n\n\ndef test_discovery_page_has_priority_sources_and_manual_add(admin_client):\n    create_event(admin_client)\n    page = admin_client.get(\n        "/admin/discovery?disaster_id=1&platform=facebook"\n    )\n    assert page.status_code == 200\n    assert "Priority missing-person sharers" in page.text\n    assert "Saigrace Pokharel / Saigrace Official" in page.text\n    assert "Hydropower Diaries" in page.text\n    assert "Manual Add" in page.text\n    assert \'id="manual-search-query"\' in page.text\n    assert "Full public post text / additional context" in page.text\n\n\ndef test_manual_intake_enriches_existing_candidate_context(admin_client):\n    create_event(admin_client)\n\n    first = admin_client.post(\n        "/admin/discovery/manual",\n        data={\n            "disaster_id": "1",\n            "platform": "facebook",\n            "url": "https://facebook.com/example/posts/123",\n            "title": "Person Missing",\n            "snippet": "Indexed snippet only.",\n            "search_query": \'site:facebook.com "Rasuwa" "missing person"\',\n        },\n        follow_redirects=False,\n    )\n    assert first.status_code == 303\n\n    second = admin_client.post(\n        "/admin/discovery/manual",\n        data={\n            "disaster_id": "1",\n            "platform": "facebook",\n            "url": "https://facebook.com/example/posts/123",\n            "snippet": "Contact 9800000000. Last seen at Timure.",\n            "search_query": \'site:facebook.com "Saigrace" "Rasuwa"\',\n        },\n        follow_redirects=False,\n    )\n    assert second.status_code == 303\n\n    with SessionLocal() as db:\n        rows = db.query(DiscoveryCandidate).all()\n        assert len(rows) == 1\n        assert "Indexed snippet only." in (rows[0].snippet or "")\n        assert "[Manual context]" in (rows[0].snippet or "")\n        assert "Contact 9800000000" in (rows[0].snippet or "")\n'}


def canonical(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def digest(path: Path) -> str:
    return hashlib.sha256(
        canonical(path.read_text(encoding="utf-8")).encode("utf-8")
    ).hexdigest()


def main() -> int:
    root = Path.cwd()

    for rel, expected in EXPECTED.items():
        path = root / rel
        if not path.is_file():
            print(f"ABORTED: expected file missing: {rel}")
            print("No files were changed.")
            return 2

        actual = digest(path)
        if actual != expected:
            print(f"ABORTED: local file differs from reviewed version: {rel}")
            print(f"Expected SHA-256: {expected}")
            print(f"Actual SHA-256:   {actual}")
            print("No files were changed.")
            return 3

    new_files = [
        "app/services/priority_sources.py",
        "tests/test_priority_source_manual_intake_upgrade.py",
    ]
    for rel in new_files:
        if (root / rel).exists():
            print(f"ABORTED: {rel} already exists.")
            print("No files were changed.")
            return 4

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = root / f".priority-source-backup-{stamp}"

    for rel in EXPECTED:
        source = root / rel
        target = backup / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)

    for rel, content in CONTENTS.items():
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="\n")

    print("PRIORITY SOURCE + MANUAL INTAKE UPGRADE APPLIED")
    print(f"Backup: {backup}")
    print("")
    print("Added:")
    print("- Saigrace, Bikki Gurung, Hydropower Diaries and other current sharers as priority search seeds")
    print("- priority sources reserved inside the bounded Wide Discovery plan")
    print("- repeat human-confirmed sources ranked higher automatically")
    print("- Manual Add buttons beside priority and targeted searches")
    print("- manual intake can enrich an existing candidate with missed public context")
    print("- no database migration required")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
